import { AppIconComponent } from '../icons/app-icon.component';

@Component({
    selector: 'app-rich-text-editor',
    standalone: true,
    imports: [CommonModule, AppIconComponent],
    template: `
    <div class="flex flex-col border border-[#ccc] rounded-md overflow-hidden bg-white shadow-sm w-full">
      
      <!-- Toolbar -->
      <div *ngIf="showToolbar || !isEmpty" class="flex items-center gap-0.5 px-2 py-1.5 border-b border-[#e6e6e6] bg-white overflow-x-auto no-scrollbar">
        <!-- Paste -->
        <button (click)="execCommand('paste')" class="p-1.5 hover:bg-[#f5f5f5] rounded transition-colors text-[#262626]" title="Paste">
            <app-icon name="paste" size="18"></app-icon>
        </button>
        
        <div class="w-px h-6 bg-[#e6e6e6] mx-1"></div>

        <!-- Font Size (Simple Dropdown Mimic) -->
        <div class="relative group">
            <button class="flex items-center gap-1.5 px-2 py-1 hover:bg-[#f5f5f5] rounded text-sm cursor-pointer transition-colors outline-none">
                <span class="text-[#262626] font-medium">{{ fontSize }}</span>
                <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" class="text-[#666]" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m6 9 6 6 6-6"/></svg>
            </button>
            <div class="absolute top-full left-0 hidden group-hover:block bg-white border border-[#e6e6e6] shadow-lg rounded-[4px] z-10 min-w-[60px] p-1">
                <div *ngFor="let size of ['14', '16', '18', '20']" 
                     (click)="setFontSize(size)"
                     class="px-3 py-1.5 hover:bg-[#e7f8fb] cursor-pointer text-sm text-[#262626] rounded-sm">
                     {{ size }}
                </div>
            </div>
        </div>

        <div class="w-px h-6 bg-[#e6e6e6] mx-1"></div>

        <!-- Bold -->
        <button (click)="execCommand('bold')" 
                [class.bg-[#e7f8fb]]="isBold" [class.text-[#007a91]]="isBold"
                class="p-1.5 hover:bg-[#f5f5f5] rounded transition-colors text-[#262626]">
          <app-icon name="bold" size="18"></app-icon>
        </button>

        <!-- Italic -->
        <button (click)="execCommand('italic')" 
                [class.bg-[#e7f8fb]]="isItalic" [class.text-[#007a91]]="isItalic"
                class="p-1.5 hover:bg-[#f5f5f5] rounded transition-colors text-[#262626]">
          <app-icon name="italic" size="18"></app-icon>
        </button>

        <!-- Underline -->
        <button (click)="execCommand('underline')" 
                [class.bg-[#e7f8fb]]="isUnderline" [class.text-[#007a91]]="isUnderline"
                class="p-1.5 hover:bg-[#f5f5f5] rounded transition-colors text-[#262626]">
          <app-icon name="underline" size="18"></app-icon>
        </button>
      </div>

      <!-- Editor Area -->
      <div #editor
           contentEditable="true"
           class="w-full px-4 py-[10px] bg-white focus:outline-none transition-colors composer-scrollbar overflow-y-auto rich-text-content"
           [style.min-height]="showToolbar ? '100px' : '44px'"
           [style.max-height]="maxHeight"
           (input)="onInput()"
           (focus)="onFocus()"
           (blur)="onBlur()"
           (keydown)="onKeyDown($event)">
      </div>

      <!-- Placeholder -->
      <div *ngIf="isEmpty && !isFocused" 
           class="absolute left-4 top-[10px] text-[#666] pointer-events-none select-none z-10"
           [style.top]="showToolbar ? '52px' : '10px'">
          {{ placeholder }}
      </div>

    </div>
  `
})
export class RichTextEditorComponent implements AfterViewInit, OnChanges {
    @Input() placeholder: string = 'Type your message...';
    @Input() content: string = '';
    @Input() showToolbar: boolean = false;
    @Input() maxHeight: string = '200px';
    @Output() contentChange = new EventEmitter<string>();
    @Output() enterPressed = new EventEmitter<void>();

    @ViewChild('editor') editorRef!: ElementRef<HTMLDivElement>;

    fontSize = '14';
    textColor = '#000000';
    highlightColor = '#ffff00';

    isBold = false;
    isItalic = false;
    isUnderline = false;
    isStrikethrough = false;

    isFocused = false;

    get isEmpty(): boolean {
        const html = this.editorRef?.nativeElement?.innerHTML || '';
        return !html || html === '<br>' || html === '<div><br></div>';
    }

    ngAfterViewInit() {
        if (this.content) {
            this.editorRef.nativeElement.innerHTML = this.content;
        }
    }

    ngOnChanges(changes: SimpleChanges) {
        if (changes['content'] && !changes['content'].firstChange) {
            if (this.editorRef && this.content !== this.editorRef.nativeElement.innerHTML) {
                this.editorRef.nativeElement.innerHTML = this.content;
            }
        }
    }

    onInput() {
        this.contentChange.emit(this.editorRef.nativeElement.innerHTML);
        this.checkActiveStyles();
    }

    onFocus() {
        this.isFocused = true;
        this.showToolbar = true; // Show toolbar on focus usually
    }

    onBlur() {
        setTimeout(() => {
            this.isFocused = false;
            // Optional: hide toolbar on blur if empty? user preference. Keeping it simple.
        }, 200);
    }

    onKeyDown(event: KeyboardEvent) {
        if (event.key === 'Enter' && !event.shiftKey) {
            event.preventDefault();
            this.enterPressed.emit();
        }
    }

    execCommand(command: string, value: string = '') {
        this.editorRef.nativeElement.focus();

        // Polyfill or standard command map
        let finalCmd = command;
        if (command === 'hiliteColor' && !document.queryCommandSupported('hiliteColor')) {
            finalCmd = 'backColor';
        }

        document.execCommand(finalCmd, false, value);
        this.onInput();
    }

    setFontSize(size: string) {
        this.fontSize = size;
        const sizeMap: Record<string, string> = { '14': '1', '16': '2', '18': '3', '20': '4' };
        this.execCommand('fontSize', sizeMap[size] || '1');
    }

    setTextColor(color: string) {
        this.textColor = color;
        this.execCommand('foreColor', color);
    }

    promptLink() {
        const url = prompt('Enter URL:');
        if (url) this.execCommand('createLink', url);
    }

    checkActiveStyles() {
        this.isBold = document.queryCommandState('bold');
        this.isItalic = document.queryCommandState('italic');
        this.isUnderline = document.queryCommandState('underline');
        this.isStrikethrough = document.queryCommandState('strikeThrough');
    }

    public clear() {
        if (this.editorRef) {
            this.editorRef.nativeElement.innerHTML = '';
            this.onInput();
        }
    }

    public focus() {
        this.editorRef?.nativeElement?.focus();
    }
}
